((SELECT id FROM m), 'Specialties', 1, 'Chicken & Waffles', 'Born in the south but perfected at Mullet''s. A giant Waffle served with fried chicken tenders and drizzled with our homemade bourbon maple glaze.', '$13.99', 13.99, ARRAY[]::text[], 14),
((SELECT id FROM m), 'Specialties', 1, 'Fraffle', 'French toast waffle, half pound burger patty, jalapeño bacon, egg, hollandaise and fried hash brown. The indentations provide a pocket of joy for your syrup.', '$15.99', 15.99, ARRAY[]::text[], 15),
((SELECT id FROM m), 'Specialties', 1, 'Eggs, Avocado & Toast*', 'Two eggs the way you like them, avocado dusted with sea salt and your choice of toast and meat.', '$13.99', 13.99, ARRAY[]::text[], 16),
((SELECT id FROM m), 'Specialties', 1, 'Breakfast Slider', 'Soft dinner roll with scrambled egg, American cheese and choice of bacon, sausage or ham. 3.99 / MAKE IT TRIO: Comes with a ham, bacon, sausage slider and side of hash. 13.99', '$13.99', 13.99, ARRAY[]::text[], 17),
((SELECT id FROM m), 'Specialties', 1, 'Breakfast Taco', 'Central Texas-style. Flour tortilla with scrambled egg, bacon, potato, cheese. Served with red or green salsa. 1/3.99 - 2/6.99. Add Brisket for 2.00 per taco.', '$2.00', 2.00, ARRAY[]::text[], 18),
