((SELECT id FROM m), 'Breakfast', 3, 'Brisket Breakfast Burrito', 'Our twist on the original. Brisket, red peppers, jalapeños, onions, cheese, and eggs. Rolled in a flour tortilla. Served with red or green salsa.', '$14.99', 14.99, ARRAY[]::text[], 27),
((SELECT id FROM m), 'Breakfast', 3, 'Country-Fried Steak', 'This will surely be your new go-to breakfast meal. Hand breaded homestyle country fried steak served with two eggs and hash browns.', '$14.99', 14.99, ARRAY[]::text[], 28),
((SELECT id FROM m), 'Breakfast', 3, 'Country-fried Steak Skillet*', 'Country potatoes, diced red and green peppers, onions, two eggs they way you like them and of course our breaded steak topped with shredded Cheddar Jack cheese and smothered in gravy.', '$14.99', 14.99, ARRAY[]::text[], 29),
((SELECT id FROM m), 'Breakfast', 3, 'Avocado Toast Flight', 'CAPRESE, B.L.T., EGGS BENEDICT We start with smashed avocado on all three as a base. The CAPRESE is topped with sliced tomatoes, fresh mozzarella, balsamic glazed and sprinkled with fresh basil. B.L.T. is topped with spring mix, jalapeño bacon and sundried tomatoes. EGGS BENEDICT starts with poached eggs smothered in hollandaise sauce and sprinkled with jalapeño bacon bits. Great as a breakfast appetizer.', '$15.99', 15.99, ARRAY[]::text[], 30),
((SELECT id FROM m), 'Breakfast', 3, 'Triple Berry French Toast', 'Three pieces of thick Texas toast each smothered with mascarpone cheese. Fresh strawberries, fresh blackberries, and fresh blueberries. Sprinkled with Fruity Pebbles and then finished with whipped cream and cherry.', '$14.99', 14.99, ARRAY[]::text[], 31),
((SELECT id FROM m), 'Breakfast', 3, 'The Country Benedict', 'We take our soft and flaky biscuits and top it with our sausage patty, a poached egg and smother it with our legendary gravy. We serve it with your choice of hash browns or country potatoes.', '$14.99', 14.99, ARRAY[]::text[], 32),
((SELECT id FROM m), 'Breakfast', 3, 'Burnt Ends Benedict*', 'A twist to the traditional Benedict. Burnt ends served on a English muffin topped with poached eggs and finished with our Alabama (white sauce) BBQ and served with hash browns.', '$15.99', 15.99, ARRAY[]::text[], 33),
((SELECT id FROM m), 'Breakfast', 3, 'Tres Leches Waffle & Eggs', 'A huge Belgian Waffle covered with fresh strawberries, sprinkled with fruity pebbles, and finished with whipped cream and cherries. Two eggs the way you like, and choice of bacon, sausage patty or ham.', '$14.99', 14.99, ARRAY[]::text[], 34),
((SELECT id FROM m), 'Breakfast', 3, 'Eggs Benedict Flight*', 'In this amazing masterpiece you get our TRADITIONAL BENEDICT (Canadian bacon and hollandaise sauce), BURNT ENDS BENEDICT (burnt ends with our Alabama white BBQ sauce), and our new AVOCADO BENNY that''s smothered in our sun-dried tomato sauce. Guaranteed to please. 15.99 (May take a little longer than standard meals)', '$15.99', 15.99, ARRAY[]::text[], 35),
((SELECT id FROM m), 'Omelets', 4, 'Denver', 'Three egg omelet with ham, red pepper, green pepper, onion and American cheese', '$14.99', 14.99, ARRAY[]::text[], 36),
