((SELECT id FROM m), 'Omelets', 4, 'Build your Omelet', 'Three egg omelet with Monterey and cheddar cheese. MEATS (+3.00) Sausage, Bacon, Ham, Jalapeño Bacon, Chorizo, Chicken, Brisket (+3.99), Pulled Pork VEGGIES & CHEESE (+75c) Onion, Mushroom, Red Pepper, Green Pepper, Banana Pepper, Jalapeño, Tomato, Spinach, Mozzarella, Pepper Jack, Cheddar Jack, American, Swiss, Gouda', '$9.99', 9.99, ARRAY[]::text[], 39),
((SELECT id FROM m), 'Classics', 5, 'Eggs Benedict', 'Two poached eggs and Canadian bacon over an English muffin smothered in hollandaise sauce. Served with hash browns. 13.99 - 1/2 ORDER 8.99 - Substitute Crab 2.99 -- Or make it a Florentine for a vegetarian option --', '$13.99', 13.99, ARRAY[]::text[], 40),
