((SELECT id FROM m), 'Specialties', 0, 'Meatloaf Hash Browns', 'Hash Browns with our homemade breakfast meatloaf mixed with red pepper, and onions and smothered with sausage gravy. Served with scrambled eggs and your choice of toast or English muffin.', '$13.49', 13.49, ARRAY[]::text[], 4),
