((SELECT id FROM m), 'Specialties', 0, 'Breakfast Taco', 'Central Texas-style. Flour tortilla with scrambled egg, bacon, potato, cheese. Served with red or green salsa | (1) $4.49, (2) $7.49 | Add Brisket for +$2 per taco', '$4.49/+', 4.49, ARRAY[]::text[], 6),
