((SELECT id FROM m), 'Specialties', 0, 'Breakfast Burrito', '(Veggie Burrito Available) Mullets Famous Burrito with chorizo, bacon, egg, potato and Cheddar Jack cheese. Served with red or green salsa | Smother it for +$1.50 (sausage gravy or Monterey Jack cheese sauce)', '$13.49', 13.49, ARRAY[]::text[], 8),
