((SELECT id FROM m), 'Specialties', 0, 'Breakfast Slider', 'Soft dinner roll with scrambled egg, American cheese and choice of bacon, sausage or ham $4.49 | Make it Trio: Comes with a ham, bacon, sausage slider and side of hash $13.49', '$4.49/+', 4.49, ARRAY[]::text[], 11),
