((SELECT id FROM m), 'Classics', 1, 'Pancakes & Eggs', 'Three pancakes, two eggs and your choice of three strips of Bacon, Two Sausage Patties or Ham | Add Chocolate Chips +$1.00 | Add Blueberries +$1.50', '$13.49', 13.49, ARRAY[]::text[], 22),
((SELECT id FROM m), 'Classics', 1, 'French Toast & Eggs', 'Three slices of French toast, two eggs and your choice of three strips of Bacon, Two Sausage Patties or Ham.', '$13.49', 13.49, ARRAY[]::text[], 23),
