((SELECT id FROM m), 'Burgers', 9, 'Slider Trio', 'Three mini burgers | Pick 3 of the following: Cheeseburger - Beef patty, American Cheese, pickle and onion | Wild West - Beef patty, Cheddar Jack cheese, bacon and BBQ sauce | The Italian - Sausage patty, marinara and mozzarella cheese | Brisket - Chopped brisket smothered in BBQ sauce topped with melted Cheddar Jack cheese.', '$14.99', 14.99, ARRAY[]::text[], 104),
((SELECT id FROM m), 'Sandwiches', 10, 'Burnt Ends', 'The point of the brisket that is smoked longest. Tossed with Mullets'' famous BBQ sauce and stacked on a toasted bun.', '$15.99', 15.99, ARRAY[]::text[], 105),
((SELECT id FROM m), 'Sandwiches', 10, 'Pork Tenderloin', 'Hand breaded pork loin with lettuce, tomato, red onion, pickle, and mayonnaise on a toasted brioche bun.', '$14.99', 14.99, ARRAY[]::text[], 106),
