((SELECT id FROM m), 'Sandwiches', 10, 'Strawberry Gouda Turkey', 'Smoked turkey on whole grain bread with Gouda, lettuce, tomato and strawberry chipotle dressing. Try it Cold or Grilled.', '$14.99', 14.99, ARRAY[]::text[], 108),
