((SELECT id FROM m), 'Sandwiches', 10, 'Philly Cheesesteak Poboy', 'Tender strips of beef grilled with red and green bell pepper, onion and Swiss American cheese. Also available with chicken | Add mushrooms +$1.49', '$14.99', 14.99, ARRAY[]::text[], 112),
