((SELECT id FROM m), 'Specialties', 0, 'The Morning Mullet', 'Two eggs, hash browns served on top of our half order of biscuits and gravy', '$13.99', 13.99, ARRAY[]::text[], 0),
((SELECT id FROM m), 'Specialties', 0, 'Bacon Chorizo Hash Browns', 'Hash browns with chorizo, bacon, red pepper, onion and covered with Swiss American cheese. Served with scrambled eggs and your choice of toast or English muffin.', '$13.99', 13.99, ARRAY[]::text[], 1),
((SELECT id FROM m), 'Specialties', 0, 'Seafood Hash', 'Shrimp, scallops, julienne red peppers and onions, topped with hash browns and covered with American Swiss cheese. Served with two eggs how you like them', '$14.99', 14.99, ARRAY[]::text[], 2),
((SELECT id FROM m), 'Specialties', 0, 'Steak Hash Browns', 'Prime sirloin diced, mushrooms, julienne onion, hash browns smothered with cheese. Served with scrambled eggs.', '$15.49', 15.49, ARRAY[]::text[], 3),
((SELECT id FROM m), 'Specialties', 0, 'Meatloaf Hash Browns', 'Hash Browns with our homemade breakfast meatloaf mixed with red pepper, onions and smothered with sausage gravy. Served with scrambled eggs and your choice of toast or English muffin.', '$13.99', 13.99, ARRAY[]::text[], 4),
((SELECT id FROM m), 'Specialties', 0, 'Chicken & Waffles', 'Born in the south but perfected at Mullet''s. A giant Waffle served with fried chicken tenders and drizzled with our homemade bourbon maple glaze.', '$13.99', 13.99, ARRAY[]::text[], 5),
((SELECT id FROM m), 'Specialties', 0, 'Tres Leches Waffle & Eggs', 'A huge Belgian Waffle covered with fresh strawberries, sprinkled with fruity pebbles, and finished with whipped cream and cherries. Two eggs the way you like, and choice of bacon, sausage patty or ham.', '$14.99', 14.99, ARRAY[]::text[], 6),
((SELECT id FROM m), 'Specialties', 0, 'Fraffle', 'French toast waffle, half pound burger patty, jalapeno bacon, egg, hollandaise and fried hash brown. The indentations provide a pocket of joy for your syrup.', '$15.99', 15.99, ARRAY[]::text[], 7),
((SELECT id FROM m), 'Specialties', 0, 'Eggs, Avocado & Toast', 'Two eggs the way you like them, avocado dusted with sea salt and your choice of toast and meat.', '$13.99', 13.99, ARRAY[]::text[], 8),
((SELECT id FROM m), 'Specialties', 0, 'Breakfast Slider', 'Soft dinner roll with scrambled egg, American cheese and choice of bacon, sausage or ham. 3.99 | MAKE IT TRIO: Comes with a ham, bacon, sausage slider and side of hash. 13.99', '$3.99', 3.99, ARRAY[]::text[], 9),
((SELECT id FROM m), 'Specialties', 0, 'Breakfast Taco', 'Central Texas-style. Flour tortilla with scrambled egg, bacon, potato, cheese. Served with red or green salsa. 1/3.99 | 2/6.99. Add Brisket for 2.00 per taco.', '1/$3.99 - 2/$6.99', 1, ARRAY[]::text[], 10),
((SELECT id FROM m), 'Specialties', 0, 'Breakfast Nachos', 'Arturo''s latest creation! Tortilla chips topped with Monterey cheese sauce and shredded cheddar jack cheese, scrambled eggs, onions, green peppers, sausage, tomatoes, bacon and jalapeños.', '$14.99', 14.99, ARRAY[]::text[], 11),
((SELECT id FROM m), 'Specialties', 0, 'Steak & Eggs', 'Prime sirloin prepared the way you like, served with two eggs and your choice of hash browns or country potatoes.', '$15.49', 15.49, ARRAY[]::text[], 12),
((SELECT id FROM m), 'Breakfast', 1, 'Breakfast Burrito (Veggie Burrito Available)', 'Mullets Famous Burrito with chorizo, bacon, egg, potato and cheddar jack cheese. Served with red or green salsa. 13.99 | Smother it for 1.50 (sausage gravy or Monterey Jack cheese sauce)', '$13.99', 13.99, ARRAY[]::text[], 13),
((SELECT id FROM m), 'Breakfast', 1, 'Brisket Breakfast Burrito', 'Our twist on the original. Brisket, red peppers, jalapeños, onions, cheese, and eggs. Rolled in a flour tortilla. Served with red or green salsa.', '$14.99', 14.99, ARRAY[]::text[], 14),
((SELECT id FROM m), 'Breakfast', 1, 'Country-Fried Steak', 'This will surely be your new go-to breakfast meal. Hand breaded homestyle country fried steak served with two eggs and hash browns.', '$14.99', 14.99, ARRAY[]::text[], 15),
((SELECT id FROM m), 'Breakfast', 1, 'Country-Fried Steak Skillet', 'Country potatoes, diced red and green peppers, onions, two eggs they way you like them and of course our breaded steak topped with shredded Cheddar Jack cheese and smothered in gravy.', '$14.99', 14.99, ARRAY[]::text[], 16),
((SELECT id FROM m), 'Breakfast', 1, 'Avocado Toast Flight', 'CAPRESE, B.L.T., EGGS BENEDICT. We start with smashed avocado on all three as a base. The CAPRESE is topped with sliced tomatoes, fresh mozzarella, balsamic glazed and sprinkled with fresh basil. B.L.T. is topped with spring mix, jalapeño bacon and sundried tomatoes. EGGS BENEDICT starts with poached eggs smothered in hollandaise sauce and sprinkled with jalapeño bacon bits. Great as a breakfast appetizer', '$15.99', 15.99, ARRAY[]::text[], 17),
((SELECT id FROM m), 'Breakfast', 1, 'Triple Berry French Toast', 'Three pieces of thick Texas toast each smothered with mascarpone cheese. Fresh strawberries, fresh blackberries, and fresh blueberries. Sprinkled with Fruity Pebbles and then finished with whipped cream and cherry', '$14.99', 14.99, ARRAY[]::text[], 18),
((SELECT id FROM m), 'Breakfast', 1, 'The Country Benedict', 'We take our soft and flaky biscuits and top it with our sausage patty, a poached egg and smother it with our legendary gravy. We serve it with your choice of hash browns or country potatoes.', '$14.99', 14.99, ARRAY[]::text[], 19),
((SELECT id FROM m), 'Breakfast', 1, 'Burnt Ends Benedict', 'A twist to the traditional Benedict. Burnt ends served on a English muffin topped with poached eggs and finished with our Alabama (white sauce) BBQ and served with hash browns.', '$15.99', 15.99, ARRAY[]::text[], 20),
((SELECT id FROM m), 'Breakfast', 1, 'Eggs Benedict Flight', 'In this amazing masterpiece you get our TRADITIONAL BENEDICT (Canadian bacon and hollandaise sauce), BURNT ENDS BENEDICT (burnt ends with our Alabama white BBQ sauce), and our AVOCADO BENNY that''s smothered in our sun-dried tomato sauce. Guaranteed to please.', '$15.99', 15.99, ARRAY[]::text[], 21),
