((SELECT id FROM m), 'Omelets', 3, 'Build Your Own Omelet', 'Three egg omelet with Monterey and cheddar cheese. 9.99 | MEATS (+3.00) Sausage, Bacon, Ham, Jalapeño Bacon, Chorizo, Chicken, Brisket (+3.99), Pulled Pork | VEGGIES & CHEESE (+75c) Onion, Mushroom, Red Pepper, Green Pepper, Banana Pepper, Jalapeño, Tomato, Spinach, Mozzarella, Pepper Jack, Cheddar Jack, American, Swiss, Gouda', '$9.99', 9.99, ARRAY[]::text[], 47),
