((SELECT id FROM m), 'Appetizers', 5, 'Sweet Po-Tator Tots', 'Your choice of savory or sweet. SAVORY STYLE - Tossed in seasoned salt and served with Sriracha hot sauce. SWEET STYLE - Tossed in cinnamon sugar and served with marshmallow cream sauce.', '$11.99', 11.99, ARRAY[]::text[], 59),
