((SELECT id FROM m), 'Entrees', 6, 'Pork Chops', 'Two French-cut pork chops grilled and served with grilled asparagus and roasted garlic mashed potatoes finished with a demi glaze.', '$26.99', 26.99, ARRAY[]::text[], 65),
