((SELECT id FROM m), 'Burgers', 11, 'Build Your Own Burger', 'Build your own burger starts with ground chuck (the best flavored burger you can buy) and a soft brioche bun, topped with lettuce, tomato, onion and pickle. MEATS +3.99: Bacon, Pork, Brisket, Chicken | VEGGIES/TOPPINGS +50c: Mayo, Jalapeño, Banana Pepper, Mushroom, Grilled Onion, Red Peppers, Green Pepper, Marinara, Ranch | CHEESE +1.00: Mozzarella, Pepper Jack, American, Swiss, Gouda, Bleu Cheese | DELUXE TOPPINGS +1.00: Coleslaw, Egg, Onion Rings, Avocado, Mac & Cheese', '$12.99', 12.99, ARRAY[]::text[], 91),
((SELECT id FROM m), 'Burgers', 11, 'Barnyard Burger', 'Half pound burger topped with Mullets'' pulled pork, homemade onion rings, two bacon strips, American and chipotle pepperjack cheese, sunny side egg, and smothered in BBQ sauce. Cow, pig, and chicken we have it all!', '$15.99', 15.99, ARRAY[]::text[], 92),
